 */
private void enlarge(final int size) {
    // Calculate the new capacity needed
    int newCapacity = data.length + size;
    // If the current data array is not large enough, create a new array with the new capacity
    if (newCapacity > data.length) {
        // Create a new array with the new capacity
        byte[] newData = new byte[newCapacity];
        // Copy the existing data to the new array
        System.arraycopy(data, 0, newData, 0, data.length);
        // Replace the old data array with the new one
        data = newData;
    }
}

