public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Separate vertices into two sets based on their keys
    List<V> setA = new ArrayList<>();
    List<V> setB = new ArrayList<>();

    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("A")) {
            setA.add(entry.getValue());
        } else if (entry.getKey().startsWith("B")) {
            setB.add(entry.getValue());
        }
    }

    // Add edges between every vertex in set A and every vertex in set B
    for (V vertexA : setA) {
        for (V vertexB : setB) {
            target.addEdge(vertexA, vertexB);
        }
    }
}

