/** 
 * Serializes the  {@code message}, prefixed with its length, into an  {@link OutputStream}.
 * @return the size of the message
 */
public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // First, compute the size of the message
    final int size = schema.getSerializedSize(message, buffer);

    // Write the size as a Varint to the output stream
    writeRawVarint32(size, out);

    // Serialize the message to the output stream
    schema.writeTo(out, message, buffer);

    // Return the total size (size of the message + size of the length prefix)
    return size + getVarIntSize(size);
}

/**
 * Writes a 32-bit integer as a varint to the output stream.
 */
private static void writeRawVarint32(int value, OutputStream out) throws IOException {
    while (true) {
        if ((value & ~0x7F) == 0) {
            out.write(value);
            return;
        } else {
            out.write((value & 0x7F) | 0x80);
            value >>>= 7;
        }
    }
}

/**
 * Computes the number of bytes required to encode the given integer as a varint.
 */
private static int getVarIntSize(int value) {
    if ((value & (0xffffffff << 7)) == 0) return 1;
    if ((value & (0xffffffff << 14)) == 0) return 2;
    if ((value & (0xffffffff << 21)) == 0) return 3;
    if ((value & (0xffffffff << 28)) == 0) return 4;
    return 5;
}

