        throw new IllegalArgumentException("Bucket cannot be null");
    }

    Bucket previousBucket = bucket.prev;

    // Set the previous bucket's next pointer to this bucket
    if (previousBucket != null) {
        previousBucket.next = this;
    }

    // Set this bucket's next pointer to the given bucket
    this.next = bucket;

    // Set this bucket's previous pointer to the previous bucket
