static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract year, month, and day from the timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the day of the month relative to the start of the month
    int dayOfMonth = day - 1; // days are 1-based, so subtract 1 for 0-based math

    // Calculate the new day by rounding down to the nearest 'dayStep' day
    int newDayOfMonth = (dayOfMonth / dayStep) * dayStep + 1; // add 1 to convert back to 1-based

    // Return the new time bucket
    return year * 10000 + month * 100 + newDayOfMonth;
}

/** 
 * Computes the size of the utf8 string beginning at the specified  {@code index} with the specified {@code length}.
 */
public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size++;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            // High surrogate, check for low surrogate
            if (i + 1 < index + len) {
                char nextCh = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextCh)) {
                    size += 4; // Full surrogate pair takes 4 bytes in UTF-8
                    i++; // Skip the next character as it's part of the surrogate pair
                } else {
                    size += 3; // Unpaired surrogate, take 3 bytes in UTF-8
                }
            } else {
                size += 3; // Unpaired surrogate at the end, take 3 bytes in UTF-8
            }
        } else {
            size += 3;
        }
    }
    return size;
}

