import java.util.Properties;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PropertyUtil {

    /** 
     * Find the value corresponding to <code>key</code> in <code>props</code>. Then perform variable substitution on the found value.
     */
    public static String findAndSubst(String key, Properties props) {
        // Initial value lookup
        String value = props.getProperty(key);
        if (value == null) {
            return null; // or throw an exception, or return an empty string, depending on requirements
        }

        // Regular expression to find variables in the format ${variable}
        Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
        Matcher matcher = pattern.matcher(value);

        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                matcher.appendReplacement(sb, Matcher.quoteReplacement(varValue));
            } else {
                matcher.appendReplacement(sb, matcher.group(0)); // keep the original if not found
            }
        }
        matcher.appendTail(sb);

        return sb.toString();
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");

        String result = findAndSubst("greeting", props);
        System.out.println(result); // Should print: Hello, World!
    }
}

