 * @param size number of additional bytes that this byte vector should be able to receive.
 */
private void enlarge(final int size) {
    if (size > 0) {
        int needed = size;
        if (this.data == null) {
            this.data = new byte[Math.max(needed, 1024)];
        } else {
            needed = needed - (this.data.length - this.length);
            if (needed > 0) {
                byte[] newData = new byte[this.data.length + Math.max(this.data.length, needed)];
                System.arraycopy(this.data, 0, newData, 0, this.length);
                this.data = newData;
            }
        }
    }
}

