protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        throw new IllegalArgumentException("Tour set and graph must not be null or empty");
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }

    // Assuming the graph is connected and the tour is a valid cycle
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);

    V currentVertex = startVertex;
    for (E edge : edgeList) {
        V nextVertex = graph.getEdgeTarget(edge);
        if (!currentVertex.equals(graph.getEdgeSource(edge))) {
            nextVertex = graph.getEdgeSource(edge);
        }
        vertexList.add(nextVertex);
        currentVertex = nextVertex;
    }

    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

