int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar CONSTANT_NameAndType_info
    for (int i = 1; i < constantPool.size(); i++) {
        Symbol existingSymbol = constantPool.get(i);
        if (existingSymbol.tag == Symbol.CONSTANT_NameAndType) {
            if (existingSymbol.name.equals(name) && existingSymbol.descriptor.equals(descriptor)) {
                return i; // Return the index of the existing symbol
            }
        }
    }

    // If no existing symbol is found, create a new one
    Symbol newSymbol = new Symbol(Symbol.CONSTANT_NameAndType, name, descriptor);
    constantPool.add(newSymbol);
    return constantPool.size() - 1; // Return the index of the new symbol
}

/** 
 * Unescape a string DOT identifier.
 * @param input the input
 * @return the unescaped output
 */
private String unescapeId(String input) {
    if (input == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\') {
            // Check for escape sequences
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                switch (nextChar) {
                    case '\\':
                        result.append('\\');
                        i++;
                        break;
                    case '\"':
                        result.append('\"');
                        i++;
                        break;
                    case 'n':
                        result.append('\n');
                        i++;
                        break;
                    case 'r':
                        result.append('\r');
                        i++;
                        break;
                    case 't':
                        result.append('\t');
                        i++;
                        break;
                    // Add more escape sequences as needed
                    default:
                        // If not a recognized escape sequence, just append the backslash and the next character
                        result.append('\\');
                        break;
                }
            } else {
                // If backslash is the last character, append it as is
                result.append('\\');
            }
        } else {
            result.append(c);
        }
        i++;
    }

    return result.toString();
}

