private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    long currentSuffixSum = 0;

    // Calculate the total sum of all elements first
    for (int bound : bounds) {
        totalSum += bound;
    }

    // Calculate the suffix sums
    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSuffixSum += bounds.get(i);
        suffixSum.add(0, (int) currentSuffixSum); // Add to the front of the list
    }

    return new Pair<>(suffixSum, totalSum);
}

/** 
 * Reverses the order of the elements in the specified range within the given array.
 * @param < V > the type of elements in the array
 * @param arr the array
 * @param from the index of the first element (inclusive) inside the range to reverse
 * @param to the index of the last element (inclusive) inside the range to reverse
 */
public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", array length=" + arr.length);
    }

    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

