public ByteVector putInt(final int intValue) {
    // Ensure there is enough space in the byte array for the int (4 bytes)
    if (length + 4 > data.length) {
        // Enlarge the data array
        int newSize = Math.max(data.length * 2, length + 4);
        byte[] newData = new byte[newSize];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
    // Put the int into the byte array in big-endian format
    data[length++] = (byte) (intValue >>> 24);
