/** 
 * Abbreviate name.
 * @param buf buffer to append abbreviation.
 * @param nameStart start of name to abbreviate.
 */
public void abbreviate(final int nameStart, final StringBuffer buf) {
    String name = buf.toString();
    if (nameStart < 0 || nameStart >= name.length()) {
        throw new IllegalArgumentException("nameStart is out of bounds");
    }

    // Split the name into words starting from the nameStart index
    String[] words = name.substring(nameStart).split("\\s+");
    StringBuilder abbreviation = new StringBuilder();

    for (String word : words) {
        if (!word.isEmpty()) {
            abbreviation.append(word.charAt(0));
        }
    }

    // Clear the buffer from nameStart to the end and append the abbreviation
    buf.delete(nameStart, buf.length());
    buf.append(abbreviation.toString().toUpperCase());
}

