private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // If the set of vertices is empty or has only one vertex, it's trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Iterate over each pair of vertices in the set
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            // Skip the same vertex
            if (!v1.equals(v2)) {
                // Check if there is an edge between v1 and v2
                if (!graph.containsEdge(v1, v2)) {
                    return false; // If any pair is not connected, it's not a clique
                }
            }
        }
    }

    // All pairs of vertices are connected, so it's a clique
    return true;
}

