    // Sort the keys to make it easier to find lower bounds
    TreeSet<K> sortedKeys = new TreeSet<>(keys);
    List<Integer> lowerBounds = new ArrayList<>();

    // For each key in the input list, find the maximum lower bound
    for (K key : keys) {
        K lowerBoundKey = sortedKeys.lower(key);
        if (lowerBoundKey == null) {
            // If no lower bound is found, you might want to add a special value, e.g., Integer.MIN_VALUE
            lowerBounds.add(Integer.MIN_VALUE);
