}

/** 
 * Pops as many abstract types from the output frame stack as described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are popped).
 */
private void pop(final String descriptor) {
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, skip '('
        index = 1;
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
        // Skip ')'
        index++;
    }
    // If it's a field descriptor, pop the single type
    if (index == 0) {
        popType(descriptor, 0);
    }
}

/**
 * Pops a single type from the output frame stack as described by the descriptor at the given index.
 * @param descriptor the descriptor string
 * @param index the starting index in the descriptor
 * @return the index after the popped type
 */
private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'Z': // boolean
        case 'C': // char
        case 'B': // byte
        case 'S': // short
        case 'I': // int
        case 'F': // float
        case 'J': // long (2 slots)
        case 'D': // double (2 slots)
            // These are all primitive types that take up 1 slot, except long and double which take 2 slots
            // For this method, we treat all as 1 slot
            index++;
            break;
        case 'L': // reference
            // Format is L<classname>;
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            index++;
            break;
        case '[': // array
            // Skip all '[' characters
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            // Then the type of the array element
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

