                ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
                allSnapshots.add(snapshot);
            }
        }

        // Filter snapshots based on the time ranges
        for (ThreadSnapshot snapshot : allSnapshots) {
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range.getStart() <= snapshot.getTime() && snapshot.getTime() <= range.getEnd()) {
                    filteredSnapshots.add(snapshot);
                    break; // No need to check other ranges once a match is found
                }
            }
        }

        return filteredSnapshots;
    }
}

